# конвейер как обычный список шагов
steps = [
    ('сборка',   True),
    ('тесты',    False),      # здесь упало
    ('выкладка', True),
]

for name, ok in steps:
    if not ok:
        print(f"✗ {name}: конвейер остановлен")
        break
    print(f"✓ {name}")
else:
    print("всё прошло, изменения в продакшне")

log = [
    '2026-08-04 10:00:01 INFO  запрос /api/users 200',
    '2026-08-04 10:00:02 ERROR база недоступна',
    '2026-08-04 10:00:03 INFO  запрос /api/users 200',
    '2026-08-04 10:00:04 ERROR таймаут платежа',
    '2026-08-04 10:00:05 WARN  очередь растёт',
]

def count_levels(lines):
    counts = {}
    for line in lines:
        for level in ('ERROR', 'WARN', 'INFO'):
            if f' {level} ' in line or f' {level}  ' in line:
                counts[level] = counts.get(level, 0) + 1
                break
    return counts

stats = count_levels(log)
print(stats)
print('ошибок:', stats.get('ERROR', 0))
if stats.get('ERROR', 0) >= 2:
    print('порог превышен — поднимаем тревогу')
